CREATE TABLE "USUARIO" (
  "idUsuario" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "dni" int NOT NULL,
  "nombre" varchar NOT NULL,
  "email" varchar UNIQUE NOT NULL,
  "contraseña" varchar NOT NULL,
  "rol" varchar NOT NULL,
  "numero_tel" varchar
);

CREATE TABLE "CLIENTE" (
  "idCliente" int PRIMARY KEY,
  "esRegistrado" boolean NOT NULL DEFAULT true
);

CREATE TABLE "VENDEDOR" (
  "idVendedor" int PRIMARY KEY,
  "numero" int
);

CREATE TABLE "PRODUCTO" (
  "idProducto" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar NOT NULL,
  "descripcion" text,
  "precio" float NOT NULL,
  "stock" int NOT NULL DEFAULT 0,
  "esDestacado" boolean DEFAULT false
);

CREATE TABLE "HISTORIAL_PRECIO" (
  "idHistorial" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "idProducto" int,
  "precioAnterior" float NOT NULL,
  "fechaCambio" datetime NOT NULL
);

CREATE TABLE "PEDIDO" (
  "idPedido" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "idCliente" int,
  "fecha" datetime NOT NULL,
  "estado" varchar NOT NULL,
  "especificaciones" text,
  "montoTotal" float NOT NULL
);

CREATE TABLE "DETALLE_PEDIDO" (
  "idDetalle" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "idPedido" int,
  "idProducto" int,
  "cantidad" int NOT NULL,
  "precioUnitario" float NOT NULL,
  "subtotal" float NOT NULL
);

CREATE TABLE "CONSULTA_CHATBOT" (
  "idConsulta" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "idCliente" int,
  "mensaje" text NOT NULL,
  "respuesta" text NOT NULL,
  "esRelevante" boolean DEFAULT true,
  "fecha" datetime NOT NULL
);

CREATE TABLE "INFORME_ANALITICO" (
  "idInforme" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "idVendedor" int,
  "fechaGeneracion" datetime NOT NULL,
  "contenidoMetricas" text,
  "sugerenciasRAG" text
);

COMMENT ON COLUMN "USUARIO"."rol" IS '''ADMIN'' o ''CLIENTE''';

ALTER TABLE "CLIENTE" ADD FOREIGN KEY ("idCliente") REFERENCES "USUARIO" ("idUsuario") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "VENDEDOR" ADD FOREIGN KEY ("idVendedor") REFERENCES "USUARIO" ("idUsuario") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "HISTORIAL_PRECIO" ADD FOREIGN KEY ("idProducto") REFERENCES "PRODUCTO" ("idProducto") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "PEDIDO" ADD FOREIGN KEY ("idCliente") REFERENCES "CLIENTE" ("idCliente") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "DETALLE_PEDIDO" ADD FOREIGN KEY ("idPedido") REFERENCES "PEDIDO" ("idPedido") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "DETALLE_PEDIDO" ADD FOREIGN KEY ("idProducto") REFERENCES "PRODUCTO" ("idProducto") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "CONSULTA_CHATBOT" ADD FOREIGN KEY ("idCliente") REFERENCES "CLIENTE" ("idCliente") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "INFORME_ANALITICO" ADD FOREIGN KEY ("idVendedor") REFERENCES "VENDEDOR" ("idVendedor") DEFERRABLE INITIALLY IMMEDIATE;
